const sourceLinksFNV = value => [...JSON.stringify(value ?? null)].reduce((h,c) => Math.imul(h ^ c.codePointAt(0),16777619) >>> 0,2166136261).toString(16).padStart(8,'0');
export function resolveTateTechnicalNode(json, sceneIndex, nodeIndex) {
  const scene = TATE_BUILDING_SCENES[sceneIndex];
  const expected = TATE_TECHNICAL_NODES[sceneIndex]?.[nodeIndex];
  const source = json?.scenes?.[sceneIndex];
  if (!scene || !expected || json?.scenes?.length !== TATE_SOURCE_SCENE_COUNT ||
      json.asset?.extras?.current !== false || json.asset?.extras?.asBuilt !== false ||
      source?.name !== scene.name || JSON.stringify(source.nodes) !== JSON.stringify(scene.rootNodes) ||
      !source.nodes.includes(expected.path[0])) return null;
  const node = json.nodes?.[nodeIndex];
  if (node?.name !== expected.name || node?.mesh !== expected.mesh ||
      sourceLinksFNV(node?.extras?.sourceLinks) !== expected.sourceLinksFNV) return null;
  for (let i=1;i<expected.path.length;i++) {
    if (!json.nodes?.[expected.path[i-1]]?.children?.includes(expected.path[i])) return null;
  }
  return expected;
}
